selectors.exact:
export interface DocumentReport {
  id: string;
  path: string;
  lifecycle: DocumentLifecycle;
  suspect: SuspectEntry[];
}

export interface CheckSummary {
  total: number;
  gating: number;
  warning: number;
  clean: number;
  /** Retired claims are listed but never clean, gating, or warning. */
  retired: number;
  doc: Record<AnchorState, number>;
  /** Claims with no evidence span are not counted here. */
  evidence: Record<EvidenceState, number>;
  /** Claims with no judge state are not counted here. */
  judge: Record<JudgeState, number>;
  expired: number;
  /** Claims with at least one conflict finding. */
  conflicts: number;
  worklist: number;
  /**
   * The contradiction pass: pairs judged, judge calls answered, pairs pending,
   * and whether it judged every pair (`store`) or only pairs with a claim in
   * the scoped document (`doc`).
   */
  conflictPass: {
    pairs: number;
    requests: number;
    pending: number;
    scope: "store" | "doc";
  };
}

export const Verdict = z
  .strictObject({
    claimId: z.string(),
    documentId: z.string(),
    kind: ClaimKind,
    doc: AnchorState,
    /** Worst state over the evidence spans; absent when the claim has none. */
    evidence: EvidenceState.optional(),
    /** Absent when no judgment applies. */
    judge: JudgeState.optional(),
    expired: z.boolean(),
    conflicts: z.array(ConflictFinding).default([]),
    gates: z.boolean(),
    /** True when the verdict warns and does not gate (SPEC 7.4); never both. */
    warns: z.boolean(),
    remediation: Remediation.nullable().default(null),
    detail: VerdictDetail,
    /** Every reason label: anchors, expiry, judge, conflicts, and gating rules. */
    reasons: z.array(z.string()).default([]),
  })
  .meta({ id: "Verdict" });
